import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { firstValueFrom } from 'rxjs';
import { Late, Session } from '../../core/session';
import { Period, closedOn, periodOn } from '../periods/periods';
import { NA, dueCents } from '../rates/rates';

/** DRAFT when added, then OPEN, then SETTLED; a DRAFT or OPEN claim can be made VOID. */
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'SETTLED' | 'VOID';

/** A status change a claim's buttons ask for. */
type ClaimAction = 'open' | 'settle' | 'void';

export interface Claim {
  id: number;
  personId: number;
  /** Always two decimals, e.g. "2.50". */
  amount: string;
  date: string;
  note: string;
  status: ClaimStatus;
  /** Given when the claim is opened and kept once VOID; null while DRAFT. */
  number: number | null;
  /** The due fixed when it was settled, two decimals; null while its due is live. */
  settledDue: string | null;
  /** The user who opened it; null while DRAFT. They cannot settle it. */
  openedBy: string | null;
  /** Bound by its person's last statement, to the due it had then. */
  stated: boolean;
  /** The due bound by its person's last statement, two decimals; null while not stated, or stated with none. */
  statedDue: string | null;
}

/** A person's rate on a date: the rate then of the grade they had then, or null when it has none. */
export type PctOn = (date: string) => string | null;

/** Only OPEN and SETTLED claims count toward what is claimed and due. */
export function counts(c: Claim): boolean {
  return c.status === 'OPEN' || c.status === 'SETTLED';
}

/** Whether the claim counts for its person held or not: a held person's OPEN claims do not. */
export function countsFor(c: Claim, held: boolean): boolean {
  return held ? c.status === 'SETTLED' : counts(c);
}

/** A claim's amount as cents, so sums are exact. */
export function cents(amount: string): number {
  const [whole, frac = ''] = amount.split('.');
  return Number(whole) * 100 + Number(frac.padEnd(2, '0'));
}

/**
 * A claim's due in cents: the due fixed when it was settled (late charge frozen in), else its figure
 * — the due bound by its person's last statement, else its amount times its person's rate on its
 * date (as `pctOn` gives it), at least the floor (in cents) — with its late charge on top;
 * null when it has none.
 */
export function claimDueCents(c: Claim, pctOn: PctOn, floorCents: number, late: Late): number | null {
  if (c.settledDue !== null) return cents(c.settledDue);
  const figure = figureCents(c, pctOn, floorCents);
  return figure === null ? null : figure + lateChargeCents(c, figure, late);
}

/** A claim's figure in cents: the due bound by its person's last statement, else its floored live due. */
function figureCents(c: Claim, pctOn: PctOn, floorCents: number): number | null {
  if (c.stated) return c.statedDue === null ? null : cents(c.statedDue);
  const pct = pctOn(c.date);
  return pct === null ? null : Math.max(dueCents(cents(c.amount), pct), floorCents);
}

/**
 * The late charge in cents on an overdue claim with the given figure: the late percent of it for
 * every full 30 days past its due-by, rounded like a due; 0 when not overdue. Never bound by a statement.
 */
export function lateChargeCents(c: Claim, figureCents: number, late: Late): number {
  if (late.today === null || !isOverdue(c, late.terms, late.today)) return 0;
  const days = Math.round((Date.parse(`${late.today}T00:00:00Z`) - Date.parse(`${dueBy(c, late.terms)}T00:00:00Z`)) / 86_400_000);
  return dueCents(figureCents * Math.floor(days / 30), late.pct);
}

/** A date (yyyy-mm-dd) the given number of days later. */
export function addDays(date: string, days: number): string {
  const d = new Date(`${date}T00:00:00Z`);
  d.setUTCDate(d.getUTCDate() + days);
  return d.toISOString().slice(0, 10);
}

/** A claim's due-by: its date plus the sheet's terms in days. */
export function dueBy(c: Claim, terms: number): string {
  return addDays(c.date, terms);
}

/** Overdue: OPEN with its due-by before the sheet's today. */
export function isOverdue(c: Claim, terms: number, today: string | null): boolean {
  return c.status === 'OPEN' && today !== null && dueBy(c, terms) < today;
}

/** Why a change to a claim dated inside a closed period is refused. */
const CLOSED = 'No claim dated inside a closed period can be changed.';

/** Why a claim dated after its person's retirement date is refused. */
export const RETIRED = 'No claim can be dated after its person\'s retirement date.';

/** Cents as an amount with two decimals. */
export function money(cents: number): string {
  return `${Math.floor(cents / 100)}.${String(cents % 100).padStart(2, '0')}`;
}

/** Why a claim cannot be edited: only a DRAFT can; an OPEN one is voided and added again. */
function notEditable(status: ClaimStatus | undefined): string {
  return status === 'OPEN'
    ? 'An OPEN claim cannot be edited; void it and add a new one.'
    : `${status ? 'A ' + status : 'This'} claim cannot be edited; only a DRAFT can.`;
}

