7	import { NA, dueCents } from '../rates/rates';
8	
9	/** DRAFT when added, then OPEN, then SETTLED; a DRAFT or OPEN claim can be made VOID. */
10	export type ClaimStatus = 'DRAFT' | 'OPEN' | 'SETTLED' | 'VOID';
11	
12	/** A status change a claim's buttons ask for. */
13	type ClaimAction = 'open' | 'settle' | 'void';
14	
15	export interface Claim {
16	  id: number;
17	  personId: number;
18	  /** Always two decimals, e.g. "2.50". */
19	  amount: string;
20	  date: string;
21	  note: string;
22	  status: ClaimStatus;
23	  /** Given when the claim is opened and kept once VOID; null while DRAFT. */
24	  number: number | null;
25	  /** The due fixed when it was settled, two decimals; null while its due is live. */
26	  settledDue: string | null;
27	  /** The user who opened it; null while DRAFT. They cannot settle it. */
28	  openedBy: string | null;
29	  /** Bound by its person's last statement, to the due it had then. */
30	  stated: boolean;
31	  /** The due bound by its person's last statement, two decimals; null while not stated, or stated with none. */
32	  statedDue: string | null;
33	}
34	
35	/** A person's rate on a date: the rate then of the grade they had then, or null when it has none. */
36	export type PctOn = (date: string) => string | null;
37	
38	/** Only OPEN and SETTLED claims count toward what is claimed and due. */
39	export function counts(c: Claim): boolean {
40	  return c.status === 'OPEN' || c.status === 'SETTLED';
41	}
42	
43	/** Whether the claim counts for its person held or not: a held person's OPEN claims do not. */
44	export function countsFor(c: Claim, held: boolean): boolean {
45	  return held ? c.status === 'SETTLED' : counts(c);
46	}
47	
48	/** A claim's amount as cents, so sums are exact. */
49	export function cents(amount: string): number {
50	  const [whole, frac = ''] = amount.split('.');
51	  return Number(whole) * 100 + Number(frac.padEnd(2, '0'));
52	}
53	
54	/**
55	 * A claim's due in cents: the due fixed when it was settled (late charge frozen in), else its figure
56	 * — the due bound by its person's last statement, else its amount times its person's rate on its
57	 * date (as `pctOn` gives it), at least the floor (in cents) — with its late charge on top;
58	 * null when it has none.
59	 */
60	export function claimDueCents(c: Claim, pctOn: PctOn, floorCents: number, late: Late): number | null {
61	  if (c.settledDue !== null) return cents(c.settledDue);
62	  const figure = figureCents(c, pctOn, floorCents);
63	  return figure === null ? null : figure + lateChargeCents(c, figure, late);
64	}
65	
66	/** A claim's figure in cents: the due bound by its person's last statement, else its floored live due. */
67	function figureCents(c: Claim, pctOn: PctOn, floorCents: number): number | null {
68	  if (c.stated) return c.statedDue === null ? null : cents(c.statedDue);
69	  const pct = pctOn(c.date);
70	  return pct === null ? null : Math.max(dueCents(cents(c.amount), pct), floorCents);
71	}
72	
73	/**
74	 * The late charge in cents on an overdue claim with the given figure: the late percent of it for
75	 * every full 30 days past its due-by, rounded like a due; 0 when not overdue. Never bound by a statement.
76	 */
77	export function lateChargeCents(c: Claim, figureCents: number, late: Late): number {
78	  if (late.today === null || !isOverdue(c, late.terms, late.today)) return 0;
79	  const days = Math.round((Date.parse(`${late.today}T00:00:00Z`) - Date.parse(`${dueBy(c, late.terms)}T00:00:00Z`)) / 86_400_000);
80	  return dueCents(figureCents * Math.floor(days / 30), late.pct);
81	}
82	
83	/** A date (yyyy-mm-dd) the given number of days later. */
84	export function addDays(date: string, days: number): string {
85	  const d = new Date(`${date}T00:00:00Z`);
86	  d.setUTCDate(d.getUTCDate() + days);
87	  return d.toISOString().slice(0, 10);
88	}
89	
90	/** A claim's due-by: its date plus the sheet's terms in days. */
91	export function dueBy(c: Claim, terms: number): string {
92	  return addDays(c.date, terms);
93	}
94	
95	/** Overdue: OPEN with its due-by before the sheet's today. */
96	export function isOverdue(c: Claim, terms: number, today: string | null): boolean {
97	  return c.status === 'OPEN' && today !== null && dueBy(c, terms) < today;
98	}
99	
100	/** Why a change to a claim dated inside a closed period is refused. */
101	const CLOSED = 'No claim dated inside a closed period can be changed.';
102	
103	/** Why a claim dated after its person's retirement date is refused. */
104	export const RETIRED = 'No claim can be dated after its person\'s retirement date.';
105	
106	/** Cents as an amount with two decimals. */
107	export function money(cents: number): string {
108	  return `${Math.floor(cents / 100)}.${String(cents % 100).padStart(2, '0')}`;
109	}
110	
111	/** Why a claim cannot be edited: only a DRAFT can; an OPEN one is voided and added again. */
112	function notEditable(status: ClaimStatus | undefined): string {
113	  return status === 'OPEN'
114	    ? 'An OPEN claim cannot be edited; void it and add a new one.'
115	    : `${status ? 'A ' + status : 'This'} claim cannot be edited; only a DRAFT can.`;
116	}
