118	// One person's claims, newest first, with one form to add a claim or edit one, and buttons to
119	// open, settle or void each claim.
120	@Component({
121	  selector: 'app-claims',
122	  imports: [ReactiveFormsModule],
123	  template: `
124	    <form [formGroup]="form" (ngSubmit)="save()" [attr.aria-label]="(editingId() === null ? 'Add claim for ' : 'Edit claim for ') + personName()">
125	      <label [for]="fieldId('amount')">Amount</label>
126	      <input [id]="fieldId('amount')" data-testid="claim-form-amount" formControlName="amount" inputmode="decimal" />
127	      <label [for]="fieldId('date')">Date</label>
128	      <input [id]="fieldId('date')" type="date" data-testid="claim-form-date" formControlName="date" />
129	      <label [for]="fieldId('note')">Note</label>
130	      <input [id]="fieldId('note')" data-testid="claim-form-note" formControlName="note" />
131	      <button type="submit" data-testid="claim-form-submit">{{ editingId() === null ? 'Add claim' : 'Save claim' }}</button>
132	      @if (error()) {
133	        <p role="alert" class="error" data-testid="claim-form-error">{{ error() }}</p>
134	      }
135	    </form>
136	    <ul [attr.aria-label]="'Claims for ' + personName()">
137	      @for (c of claims(); track c.id) {
138	        <li [attr.data-testid]="'claim-row-' + c.id">
139	          <span>No. <span data-testid="claim-number">{{ c.number ?? '' }}</span></span>
140	          <span data-testid="claim-amount">{{ c.amount }}</span>
141	          <span data-testid="claim-date">{{ c.date }}</span>
142	          <span data-testid="claim-note">{{ c.note }}</span>
143	          <span>Period <span data-testid="claim-period">{{ periodOf(c) }}</span></span>
144	          <span>Due <span data-testid="claim-due">{{ dueOf(c) }}</span></span>
145	          <span data-testid="claim-status">{{ c.status }}</span>
146	          <span>Opened by <span data-testid="claim-opened-by">{{ c.openedBy ?? '' }}</span></span>
147	          <span>Stated <span data-testid="claim-stated">{{ c.stated ? 'yes' : 'no' }}</span></span>
148	          <span>Due by <span data-testid="claim-due-by">{{ dueByOf(c) }}</span></span>
149	          <span>Overdue <span data-testid="claim-overdue">{{ overdueOf(c) ? 'yes' : 'no' }}</span></span>
150	          <button type="button" data-testid="claim-open" (click)="act(c, 'open')"
151	                  [attr.aria-label]="'Open claim of ' + c.amount + ' on ' + c.date">Open</button>
152	          <button type="button" data-testid="claim-settle" (click)="act(c, 'settle')"
153	                  [attr.aria-label]="'Settle claim of ' + c.amount + ' on ' + c.date">Settle</button>
154	          <button type="button" data-testid="claim-void" (click)="act(c, 'void')"
155	                  [attr.aria-label]="'Void claim of ' + c.amount + ' on ' + c.date">Void</button>
156	          @if (editingId() === c.id) {
157	            <button type="button" data-testid="claim-cancel" (click)="cancel()">Cancel</button>
158	          } @else {
159	            <button type="button" data-testid="claim-edit" (click)="edit(c)"
160	                    [attr.aria-label]="'Edit claim of ' + c.amount + ' on ' + c.date">Edit</button>
161	          }
162	          @if (claimError()?.id === c.id) {
163	            <p role="alert" class="error" data-testid="claim-error">{{ claimError()?.message }}</p>
164	          }
165	        </li>
166	      }
167	    </ul>
168	  `,
169	})
170	export class Claims {
171	  private readonly http = inject(HttpClient);
172	  private readonly session = inject(Session);
173	
174	  readonly personId = input.required<number>();
175	  readonly personName = input.required<string>();
176	  readonly claims = input.required<Claim[]>();
177	  /** The person's rate on a date, of the grade they had then. */
178	  readonly pctOn = input.required<PctOn>();
179	  /** The sheet's periods, for the one each claim's date falls in. */
180	  readonly periods = input.required<Period[]>();
181	  /** A claim added, edited or given a new status, as the store now holds it. */
182	  readonly saved = output<Claim>();
183	
184	  protected readonly editingId = signal<number | null>(null);
185	  /** A submit is under way; another one waits for its answer rather than storing twice. */
186	  private saving = false;
187	  protected readonly error = signal('');
188	  /** The error from the last action on a claim's row, if it was refused. */
189	  protected readonly claimError = signal<{ id: number; message: string } | null>(null);
190	  protected readonly form = new FormGroup({
191	    amount: new FormControl('', { nonNullable: true }),
192	    date: new FormControl('', { nonNullable: true }),
193	    note: new FormControl('', { nonNullable: true }),
194	  });
195	
196	  constructor() {
197	    this.form.valueChanges.subscribe(() => this.error.set(''));
198	  }
199	
200	  protected fieldId(field: string): string {
201	    return `claim-${this.personId()}-${field}`;
202	  }
203	
204	  /** The due fixed when it was settled, else its figure with its late charge on top. */
205	  protected dueOf(c: Claim): string {
206	    const due = claimDueCents(c, this.pctOn(), cents(this.session.floor()), this.session.late());
207	    return due === null ? NA : money(due);
208	  }
209	
210	  protected dueByOf(c: Claim): string {
211	    return dueBy(c, this.session.terms());
212	  }
213	
214	  protected overdueOf(c: Claim): boolean {
215	    return isOverdue(c, this.session.terms(), this.session.today());
216	  }
217	
218	  /** The name of the period its date falls in, or blank when none. */
219	  protected periodOf(c: Claim): string {
220	    return periodOn(this.periods(), c.date)?.name ?? '';
221	  }
222	
223	  private headers(): Record<string, string> {
224	    return { 'X-User': this.session.user() ?? '' };
225	  }
226	
227	  private reset(): void {
228	    this.editingId.set(null);
229	    this.form.reset({ amount: '', date: '', note: '' }, { emitEvent: false });
230	    this.error.set('');
231	  }
232	
233	  protected edit(c: Claim): void {
234	    this.claimError.set(null);
235	    if (closedOn(this.periods(), c.date)) {
236	      this.claimError.set({ id: c.id, message: CLOSED });
237	      return;
238	    }
239	    if (c.status !== 'DRAFT') {
240	      this.claimError.set({ id: c.id, message: notEditable(c.status) });
241	      return;
242	    }
243	    this.editingId.set(c.id);
244	    this.form.setValue({ amount: c.amount, date: c.date, note: c.note }, { emitEvent: false });
245	    this.error.set('');
246	  }
247	
248	  protected cancel(): void {
249	    this.reset();
250	  }
251	
252	  /** Open, settle or void a claim; a change its status does not allow is refused. */
253	  protected async act(c: Claim, action: ClaimAction): Promise<void> {
254	    this.claimError.set(null);
255	    const sheet = this.session.sheetId();
256	    if (!sheet) return;
257	    const url = `/api/sheets/${encodeURIComponent(sheet)}/claims/${c.id}/${action}`;
258	    try {
259	      const claim = await firstValueFrom(this.http.post<Claim>(url, null, { headers: this.headers() }));
260	      if (this.session.sheetId() !== sheet) return;
261	      this.saved.emit(claim);
262	    } catch (e) {
263	      if (this.session.sheetId() !== sheet) return;
264	      const message = e instanceof HttpErrorResponse && e.status === 423
265	        ? CLOSED
266	        : e instanceof HttpErrorResponse && e.status === 403
267	        ? 'The user who opened a claim cannot settle it.'
268	        : e instanceof HttpErrorResponse && e.status === 422
269	        ? 'A clerk cannot settle a claim whose due is above the clerk limit.'
270	        : e instanceof HttpErrorResponse && e.status === 409
271	        ? `A ${c.status} claim cannot be ${action === 'open' ? 'opened' : action === 'settle' ? 'settled' : 'voided'}.`
272	        : 'Could not change that claim.';
273	      this.claimError.set({ id: c.id, message });
274	    }
275	  }
276	
277	  protected async save(): Promise<void> {
278	    if (this.saving) return;
279	    this.error.set('');
280	    this.claimError.set(null);
281	    const sheet = this.session.sheetId();
282	    if (!sheet) return;
283	    const raw = this.form.getRawValue();
284	    const amount = raw.amount.trim();
285	    const date = raw.date.trim();
286	    if (!/^\d{1,12}(\.\d{1,2})?$/.test(amount)) {
287	      this.error.set('Enter an amount of 0.00 or more, with at most two decimals.');
288	      return;
289	    }
290	    if (date && !/^\d{4}-\d{2}-\d{2}$/.test(date)) {
291	      this.error.set('Enter a date, or leave it blank for today.');
292	      return;
293	    }
294	    const body = { amount, date: date || null, note: raw.note.trim() };
295	    const id = this.editingId();
296	    const base = `/api/sheets/${encodeURIComponent(sheet)}`;
297	    this.saving = true;
298	    try {
299	      const claim = await firstValueFrom(
300	        id === null
301	          ? this.http.post<Claim>(`${base}/people/${this.personId()}/claims`, body, { headers: this.headers() })
302	          : this.http.put<Claim>(`${base}/claims/${id}`, body, { headers: this.headers() }),
303	      );
304	      if (this.session.sheetId() !== sheet) return;
305	      this.saved.emit(claim);
306	      this.reset();
307	    } catch (e) {
308	      if (this.session.sheetId() !== sheet) return;
309	      if (id !== null && e instanceof HttpErrorResponse && e.status === 409) {
310	        const status = this.claims().find((c) => c.id === id)?.status;
311	        this.claimError.set({ id, message: notEditable(status) });
312	        return;
313	      }
314	      this.error.set(
315	        e instanceof HttpErrorResponse && e.status === 423
316	          ? CLOSED
317	          : e instanceof HttpErrorResponse && e.status === 422
318	          ? RETIRED
319	          : id === null ? 'Could not add that claim.' : 'Could not save that claim.',
320	      );
321	    } finally {
322	      this.saving = false;
323	    }
324	  }
325	}
